URL = "http://127.0.0.1:33975/mcp/904976312d4052b9854ea822597aeca3"

def _call(payload, tries=6):
    last = None
    for i in range(tries):
        try:
            data = json.dumps(payload).encode()
            req = urllib.request.Request(URL, data=data, headers={
                "Content-Type": "application/json",
                "Accept": "application/json, text/event-stream",
            })
            with urllib.request.urlopen(req, timeout=90) as r:
                body = r.read().decode()
            if body.lstrip().startswith("event:") or body.lstrip().startswith("data:"):
                parts = [l[5:].strip() for l in body.splitlines() if l.startswith("data:")]
                body = "\n".join(parts)
            return json.loads(body)
        except Exception as e:
            last = e
            time.sleep(0.8 * (i + 1))
    return {"error": str(last)}

def one(tool, args):
    res = _call({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":tool,"arguments":args}})
    if "error" in res:
        return {"error": res["error"]}
    r = res.get("result", {})
    out = [c["text"] for c in r.get("content", []) if c.get("type") == "text"]
    txt = "\n".join(out)
    try:
        return json.loads(txt)
    except Exception:
        return txt

def main():
    spec = json.load(sys.stdin)
    tool = spec["tool"]
    calls = spec["calls"]
    results = []
    for a in calls:
        results.append(one(tool, a))
    print(json.dumps(results if len(results) > 1 else results[0], indent=1, ensure_ascii=False))

